const body = $input.all()[0].json.body;
if (body.event !== 'appointment.updated') return [];
const before = body.data.before || {};
const after = body.data.after || body.data;
const dtChanged = (before.startTime !== after.startTime) || (before.endTime !== after.endTime);
if (!dtChanged) return [{ json: { skip: true, reason: 'Datetime unchanged' } }];
return [{ json: { skip: false, after, before, tenantId: after.tenantId, appointmentId: after.id } }];

